package com.colovision.security;
import io.jsonwebtoken.Claims; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import java.util.*; import org.springframework.context.annotation.*; import org.springframework.http.HttpHeaders; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.web.*; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.web.filter.OncePerRequestFilter;
@Configuration @EnableWebSecurity public class SecurityConfig { @Bean SecurityFilterChain chain(HttpSecurity h,JwtService jwt)throws Exception{return h.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/health","/api/auth/**","/error").permitAll().anyRequest().authenticated()).addFilterBefore(new Filter(jwt),UsernamePasswordAuthenticationFilter.class).build();} static class Filter extends OncePerRequestFilter { final JwtService jwt; Filter(JwtService jwt){this.jwt=jwt;} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String h=r.getHeader(HttpHeaders.AUTHORIZATION); if(h!=null&&h.startsWith("Bearer "))try{Claims x=jwt.parse(h.substring(7)); var a=new SimpleGrantedAuthority("ROLE_"+x.get("role",String.class).toUpperCase()); var auth=new UsernamePasswordAuthenticationToken(x.getSubject(),null,List.of(a)); org.springframework.security.core.context.SecurityContextHolder.getContext().setAuthentication(auth);}catch(Exception ignored){} c.doFilter(r,s);}} }
